'use client';

import { useCallback, useEffect, useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Sheet, SheetContent, SheetTitle } from '@/registry/ndeko/ui/sheet';

import { AppSidebar, type PageCounts } from './app-sidebar';
import { BoardPage } from './board-page';
import { tasksInColumnsOf, type Columns } from './board-model';
import {
  CURRENT_USER_ID,
  INBOX,
  NAV_GROUPS,
  PEOPLE,
  TASKS,
  WORKSPACES,
  type FeedComment,
  type InboxItem,
  type NavItem,
  type PageId,
  type StatusId,
  type Task,
} from './data';
import { InboxPage } from './inbox-page';
import { InboxPopover } from './inbox-popover';
import type { CreateKind } from './quick-create-menu';
import { CommandPalette } from './search-palette';
import { TaskDrawer } from './task-drawer';
import { newTaskOf, patchedTask, withComment } from './task-edits';
import { NEW_TASK_STATUS, TaskListPage } from './task-list-page';
import { currentUser, isAssignedTo, nextNumberOf } from './task-model';
import { TeamPage } from './team-page';
import { TopBar } from './top-bar';
import { useTeam } from './use-team';

const NAV_ITEMS = NAV_GROUPS.flatMap((group) => group.items);

function navItemOf(pageId: PageId): NavItem {
  const item = NAV_ITEMS.find((candidate) => candidate.id === pageId);
  if (item) {
    return item;
  }
  return NAV_ITEMS[0];
}

function ancestorOf(pageId: PageId) {
  const group = NAV_GROUPS.find((candidate) =>
    candidate.items.some((item) => item.id === pageId)
  );
  return group?.team?.name;
}

function replacedTask(
  tasks: Task[],
  taskId: string,
  update: (task: Task) => Task
) {
  return tasks.map((task) => {
    if (task.id !== taskId) {
      return task;
    }
    return update(task);
  });
}

function withRead(items: InboxItem[], itemId: string, isUnread: boolean) {
  return items.map((item) => {
    if (item.id !== itemId) {
      return item;
    }
    return { ...item, isUnread };
  });
}

function inboxSequenceOf(items: InboxItem[], tasks: Task[]) {
  const ids: string[] = [];
  for (const item of items) {
    const task = tasks.find(
      (candidate) => candidate.number === item.taskNumber
    );
    const isNew = task !== undefined && !ids.includes(task.id);
    if (task && isNew) {
      ids.push(task.id);
    }
  }
  return ids;
}

function isTypingTarget(target: EventTarget | null) {
  if (!(target instanceof HTMLElement)) {
    return false;
  }
  const isField = target.matches('input, textarea, select');
  return isField || target.isContentEditable;
}

function isPaletteShortcut(event: KeyboardEvent) {
  const isKKey = event.key.toLowerCase() === 'k';
  const hasModifier = event.metaKey || event.ctrlKey;
  return isKKey && hasModifier;
}

function isCreateShortcut(event: KeyboardEvent) {
  const isCKey = event.key.toLowerCase() === 'c';
  const hasModifier = event.metaKey || event.ctrlKey || event.altKey;
  const isTyping = isTypingTarget(event.target);
  return isCKey && !hasModifier && !isTyping;
}

function keepWorkspace() {
  return undefined;
}

export default function Application01() {
  const [activePageId, setActivePageId] = useState<PageId>('my-tasks');
  const [isSidebarHidden, setIsSidebarHidden] = useState(false);
  const [isNavigationOpen, setIsNavigationOpen] = useState(false);
  const [isPaletteOpen, setIsPaletteOpen] = useState(false);
  const [tasks, setTasks] = useState<Task[]>(TASKS);
  const [inbox, setInbox] = useState<InboxItem[]>(INBOX);
  const [draftStatus, setDraftStatus] = useState<StatusId | null>(null);
  const [openTaskId, setOpenTaskId] = useState<string | null>(null);
  const [shownTaskId, setShownTaskId] = useState<string | null>(null);
  const [sequence, setSequence] = useState<string[]>([]);
  const team = useTeam();

  const workspace = WORKSPACES[0];
  const activePage = navItemOf(activePageId);
  const ancestor = ancestorOf(activePageId);
  const me = currentUser();
  const myTasks = tasks.filter((task) => isAssignedTo(task, CURRENT_USER_ID));
  const myOpenTasks = myTasks.filter((task) => task.status !== 'done');
  const unreadItems = inbox.filter((item) => item.isUnread);
  const isDrawerOpen = openTaskId !== null;
  const counts: PageCounts = {
    inbox: unreadItems.length,
    'my-tasks': myOpenTasks.length,
  };

  const startNewTask = useCallback(() => {
    setIsNavigationOpen(false);
    setActivePageId('my-tasks');
    setDraftStatus(NEW_TASK_STATUS);
  }, []);

  const showTask = useCallback((taskId: string) => {
    setOpenTaskId(taskId);
    setShownTaskId(taskId);
  }, []);

  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (isPaletteShortcut(event)) {
        event.preventDefault();
        setIsPaletteOpen((isOpen) => !isOpen);
        return;
      }
      if (isDrawerOpen) {
        return;
      }
      if (isCreateShortcut(event)) {
        event.preventDefault();
        startNewTask();
      }
    }

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isDrawerOpen, startNewTask]);

  function navigate(pageId: PageId) {
    setActivePageId(pageId);
    setIsNavigationOpen(false);
  }

  function create(kind: CreateKind) {
    if (kind === 'task') {
      startNewTask();
      return;
    }
    navigate('team');
  }

  function openSearch() {
    setIsNavigationOpen(false);
    setIsPaletteOpen(true);
  }

  function hideSidebar() {
    setIsSidebarHidden(true);
  }

  function showSidebar() {
    setIsSidebarHidden(false);
  }

  function openNavigation() {
    setIsNavigationOpen(true);
  }

  function openTask(taskId: string, nextSequence: string[]) {
    setSequence(nextSequence);
    showTask(taskId);
  }

  function closeDrawer() {
    setOpenTaskId(null);
  }

  function patchTask(taskId: string, patch: Partial<Task>) {
    setTasks((current) =>
      replacedTask(current, taskId, (task) => patchedTask(task, patch))
    );
  }

  function commentOnTask(taskId: string, comment: FeedComment) {
    setTasks((current) =>
      replacedTask(current, taskId, (task) => withComment(task, comment))
    );
  }

  function addTask(status: StatusId, title: string, assigneeIds: string[]) {
    const number = nextNumberOf(tasks);
    const task = newTaskOf(number, status, title, assigneeIds);
    setTasks((current) => [task, ...current]);
    return task.id;
  }

  function createMyTask(status: StatusId, title: string) {
    addTask(status, title, [CURRENT_USER_ID]);
  }

  function createBoardTask(status: StatusId, title: string) {
    return addTask(status, title, []);
  }

  function applyColumns(columns: Columns) {
    setTasks((current) => tasksInColumnsOf(current, columns));
  }

  function openInboxItem(itemId: string) {
    const item = inbox.find((entry) => entry.id === itemId);
    setInbox((current) => withRead(current, itemId, false));
    if (!item) {
      return;
    }
    const task = tasks.find((entry) => entry.number === item.taskNumber);
    if (!task) {
      return;
    }
    openTask(task.id, inboxSequenceOf(inbox, tasks));
  }

  function toggleRead(itemId: string) {
    const item = inbox.find((entry) => entry.id === itemId);
    if (!item) {
      return;
    }
    setInbox((current) => withRead(current, itemId, !item.isUnread));
  }

  function archive(itemId: string) {
    setInbox((current) => current.filter((item) => item.id !== itemId));
  }

  function markAllRead() {
    setInbox((current) =>
      current.map((item) => ({ ...item, isUnread: false }))
    );
  }

  const sidebarProps = {
    workspaces: WORKSPACES,
    workspace,
    onWorkspaceChange: keepWorkspace,
    groups: NAV_GROUPS,
    activePageId,
    counts,
    person: me,
    onNavigate: navigate,
    onOpenSearch: openSearch,
    onCreate: create,
  };

  const inboxActions = {
    onOpen: openInboxItem,
    onToggleRead: toggleRead,
    onArchive: archive,
    onMarkAllRead: markAllRead,
  };

  return (
    <div className='bg-sidebar text-foreground flex h-dvh min-h-0 w-full md:p-2'>
      <aside aria-label='Sidebar' className='hidden shrink-0 md:block'>
        <AnimatedSize
          axis='width'
          inert={isSidebarHidden}
          className='m-0 h-full'
          contentClassName={cn('h-full p-0', isSidebarHidden && 'w-0')}
        >
          <div className='h-full w-60 pr-2'>
            <AppSidebar {...sidebarProps} onHide={hideSidebar} />
          </div>
        </AnimatedSize>
      </aside>
      <Sheet open={isNavigationOpen} onOpenChange={setIsNavigationOpen}>
        <SheetContent
          side='left'
          showCloseButton={false}
          className='bg-sidebar w-72 gap-0 p-2'
        >
          <SheetTitle className='sr-only'>Navigation</SheetTitle>
          <AppSidebar {...sidebarProps} />
        </SheetContent>
      </Sheet>
      <main className='bg-background md:hairline-ring md:ring-border flex min-w-0 flex-1 flex-col overflow-clip md:rounded-xl md:shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        <TopBar
          page={activePage}
          ancestor={ancestor}
          people={PEOPLE}
          isSidebarHidden={isSidebarHidden}
          onShowSidebar={showSidebar}
          onOpenNavigation={openNavigation}
        >
          <InboxPopover items={inbox} {...inboxActions} />
        </TopBar>
        {activePageId === 'inbox' && (
          <InboxPage items={inbox} {...inboxActions} />
        )}
        {activePageId === 'my-tasks' && (
          <TaskListPage
            tasks={myTasks}
            openTaskId={openTaskId}
            draftStatus={draftStatus}
            onDraftStatusChange={setDraftStatus}
            onOpenTask={openTask}
            onPatchTask={patchTask}
            onCreateTask={createMyTask}
          />
        )}
        {activePageId === 'board' && (
          <BoardPage
            tasks={tasks}
            onColumnsChange={applyColumns}
            onCreateTask={createBoardTask}
          />
        )}
        {activePageId === 'team' && <TeamPage team={team} />}
      </main>
      <TaskDrawer
        tasks={tasks}
        sequence={sequence}
        openTaskId={openTaskId}
        shownTaskId={shownTaskId}
        onOpenTask={showTask}
        onClose={closeDrawer}
        onPatch={patchTask}
        onComment={commentOnTask}
      />
      <CommandPalette
        open={isPaletteOpen}
        onOpenChange={setIsPaletteOpen}
        groups={NAV_GROUPS}
        onNavigate={navigate}
        onCreateTask={startNewTask}
      />
    </div>
  );
}

'use client';

import { useId } from 'react';

import { LayoutIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { AccountMenu } from './account-menu';
import type { NavGroup, NavItem, PageId, Person, Workspace } from './data';
import { QuickCreateMenu, type CreateKind } from './quick-create-menu';
import { SearchTrigger } from './search-palette';
import { EntityTile, NavRow } from './sidebar-parts';
import { WorkspaceSwitcher } from './workspace-switcher';

export type PageCounts = Partial<Record<PageId, number>>;

type AppSidebarProps = {
  workspaces: Workspace[];
  workspace: Workspace;
  onWorkspaceChange: (workspaceId: string) => void;
  groups: NavGroup[];
  activePageId: PageId;
  counts: PageCounts;
  person: Person;
  onNavigate: (pageId: PageId) => void;
  onOpenSearch: () => void;
  onCreate: (kind: CreateKind) => void;
  onHide?: () => void;
};

function GroupLabel({ group }: { group: NavGroup }) {
  if (group.team) {
    return (
      <p className='text-muted-foreground flex h-6 items-center gap-2 px-2 text-xs font-medium'>
        <EntityTile entity={group.team} size='xs' />
        {group.team.name}
      </p>
    );
  }
  if (group.label) {
    return (
      <p className='text-muted-foreground flex h-6 items-center px-2 text-xs font-medium'>
        {group.label}
      </p>
    );
  }
  return null;
}

export function AppSidebar({
  workspaces,
  workspace,
  onWorkspaceChange,
  groups,
  activePageId,
  counts,
  person,
  onNavigate,
  onOpenSearch,
  onCreate,
  onHide,
}: AppSidebarProps) {
  const indicatorId = useId();
  const canHide = Boolean(onHide);

  function selectItem(item: NavItem) {
    onNavigate(item.id);
  }

  return (
    <div className='flex h-full min-h-0 flex-col gap-3'>
      <div className='flex flex-col gap-2'>
        <div className='flex items-center gap-1'>
          <WorkspaceSwitcher
            workspaces={workspaces}
            current={workspace}
            onSelect={onWorkspaceChange}
          />
          {canHide && (
            <Button
              variant='ghost'
              size='icon-sm'
              aria-label='Hide sidebar'
              onClick={onHide}
              className='text-muted-foreground'
            >
              <LayoutIcon />
            </Button>
          )}
        </div>
        <div className='flex items-center gap-2'>
          <SearchTrigger onOpen={onOpenSearch} />
          <QuickCreateMenu onCreate={onCreate} />
        </div>
      </div>
      <nav
        aria-label='Main'
        className='-mx-2 flex min-h-0 flex-1 flex-col gap-4 overflow-y-auto px-2'
      >
        {groups.map((group) => (
          <div key={group.id} className='flex flex-col gap-0.5'>
            <GroupLabel group={group} />
            <ul className='flex flex-col gap-px'>
              {group.items.map((item) => (
                <NavRow
                  key={item.id}
                  item={item}
                  isActive={item.id === activePageId}
                  indicatorId={indicatorId}
                  count={counts[item.id]}
                  onSelect={selectItem}
                />
              ))}
            </ul>
          </div>
        ))}
      </nav>
      <AccountMenu person={person} />
    </div>
  );
}

'use client';

import { motion, type Transition, useReducedMotion } from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';

import type { Entity, NavItem } from './data';
import { RollingCount } from './motion-parts';

export const NAV_ROW = [
  'relative flex h-7 w-full min-w-0 items-center gap-2 rounded-md px-2 text-left text-[13px] font-medium text-foreground outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
  "[&_svg]:pointer-events-none [&_svg]:relative [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
].join(' ');

const INDICATOR_TRAVEL: Transition = {
  duration: 0.25,
  ease: [0.77, 0, 0.175, 1],
};

const INSTANT: Transition = { duration: 0 };

function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return INDICATOR_TRAVEL;
}

/** The one highlight of the active row. It travels from the old row to the new one. */
export function ActiveRowIndicator({ layoutId }: { layoutId: string }) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.span
      aria-hidden='true'
      layoutId={layoutId}
      transition={travelOf(shouldReduceMotion)}
      className='bg-foreground/[0.07] absolute inset-0 rounded-md'
    />
  );
}

const TILE_SIZE = {
  xs: 'size-4 rounded-[4px] text-[9px]',
  sm: 'size-5 rounded-[5px] text-[10px]',
  md: 'size-6 rounded-md text-[11px]',
} as const;

export function EntityTile({
  entity,
  size = 'md',
  className,
}: {
  entity: Entity;
  size?: keyof typeof TILE_SIZE;
  className?: string;
}) {
  const tileStyle = { '--gem': entity.color } as React.CSSProperties;

  return (
    <span
      aria-hidden='true'
      style={tileStyle}
      className={cn(
        'gem-plate inline-flex shrink-0 items-center justify-center font-semibold',
        TILE_SIZE[size],
        className
      )}
    >
      {entity.initials}
    </span>
  );
}

export function ariaCurrentOf(isActive: boolean) {
  if (isActive) {
    return 'page' as const;
  }
  return undefined;
}

type NavRowProps = {
  item: NavItem;
  isActive: boolean;
  indicatorId: string;
  count?: number;
  onSelect: (item: NavItem) => void;
};

export function NavRow({
  item,
  isActive,
  indicatorId,
  count = 0,
  onSelect,
}: NavRowProps) {
  const hasCount = count > 0;
  const ItemIcon = item.icon;
  const ariaCurrent = ariaCurrentOf(isActive);

  function selectItem() {
    onSelect(item);
  }

  return (
    <li>
      <button
        type='button'
        aria-current={ariaCurrent}
        onClick={selectItem}
        className={NAV_ROW}
      >
        {isActive && <ActiveRowIndicator layoutId={indicatorId} />}
        <ItemIcon />
        <span className='relative min-w-0 flex-1 truncate'>{item.label}</span>
        {hasCount && (
          <RollingCount
            value={count}
            className='text-muted-foreground text-xs font-normal'
          />
        )}
      </button>
    </li>
  );
}

'use client';

import {
  ChevronsUpDownIcon,
  PlusIcon,
  SettingsIcon,
} from '@/registry/ndeko/lib/icons';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { Workspace } from './data';
import { EntityTile } from './sidebar-parts';

const TRIGGER = [
  'flex h-9 min-w-0 flex-1 items-center gap-2 rounded-md px-1.5 text-left outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 data-popup-open:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
].join(' ');

function memberCountLabelOf(count: number) {
  if (count === 1) {
    return '1 member';
  }
  return `${count} members`;
}

type WorkspaceSwitcherProps = {
  workspaces: Workspace[];
  current: Workspace;
  onSelect: (workspaceId: string) => void;
};

export function WorkspaceSwitcher({
  workspaces,
  current,
  onSelect,
}: WorkspaceSwitcherProps) {
  function selectWorkspace(value: unknown) {
    if (typeof value === 'string') {
      onSelect(value);
    }
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <button
            type='button'
            aria-label={`Workspace: ${current.name}`}
            className={TRIGGER}
          />
        }
      >
        <EntityTile entity={current} />
        <span className='min-w-0 flex-1 truncate text-[13px] font-semibold'>
          {current.name}
        </span>
        <ChevronsUpDownIcon className='text-muted-foreground size-3.5 shrink-0' />
      </DropdownMenuTrigger>
      <DropdownMenuContent className='w-64'>
        <DropdownMenuLabel>Workspaces</DropdownMenuLabel>
        <DropdownMenuRadioGroup
          value={current.id}
          onValueChange={selectWorkspace}
        >
          {workspaces.map((workspace) => (
            <DropdownMenuRadioItem
              key={workspace.id}
              value={workspace.id}
              closeOnClick
              className='h-9'
            >
              <EntityTile entity={workspace} size='sm' />
              <span className='min-w-0 flex-1 truncate'>{workspace.name}</span>
              <Kbd aria-hidden='true'>{workspace.memberCount}</Kbd>
              <span className='sr-only'>
                {memberCountLabelOf(workspace.memberCount)}
              </span>
            </DropdownMenuRadioItem>
          ))}
        </DropdownMenuRadioGroup>
        <DropdownMenuSeparator />
        <DropdownMenuItem>
          <SettingsIcon />
          Workspace settings
        </DropdownMenuItem>
        <DropdownMenuItem>
          <PlusIcon />
          Add workspace
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

'use client';

import { CircleCheckIcon, SearchIcon } from '@/registry/ndeko/lib/icons';
import { CONTROL_RECIPE } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandShortcut,
} from '@/registry/ndeko/ui/command';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { NavGroup, PageId } from './data';

function headingOf(group: NavGroup) {
  if (group.team) {
    return group.team.name;
  }
  if (group.label) {
    return group.label;
  }
  return 'Personal';
}

export function SearchTrigger({ onOpen }: { onOpen: () => void }) {
  return (
    <button
      type='button'
      onClick={onOpen}
      className={cn(
        CONTROL_RECIPE,
        'text-muted-foreground flex h-8 min-w-0 flex-1 cursor-pointer items-center gap-2 px-2.5 text-left'
      )}
    >
      <SearchIcon className='size-4 shrink-0' />
      <span className='min-w-0 flex-1 truncate'>Search</span>
      <Kbd>⌘K</Kbd>
    </button>
  );
}

type CommandPaletteProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  groups: NavGroup[];
  onNavigate: (pageId: PageId) => void;
  onCreateTask: () => void;
};

export function CommandPalette({
  open,
  onOpenChange,
  groups,
  onNavigate,
  onCreateTask,
}: CommandPaletteProps) {
  function closePalette() {
    onOpenChange(false);
  }

  function createTask() {
    closePalette();
    onCreateTask();
  }

  return (
    <CommandDialog
      open={open}
      onOpenChange={onOpenChange}
      title='Search'
      description='Go to a page or run an action'
    >
      <CommandInput placeholder='Go to a page or run an action' />
      <CommandList>
        <CommandEmpty>Nothing matches. Try the name of a page.</CommandEmpty>
        <CommandGroup heading='Actions'>
          <CommandItem onSelect={createTask}>
            <CircleCheckIcon />
            New task
            <CommandShortcut>C</CommandShortcut>
          </CommandItem>
        </CommandGroup>
        {groups.map((group) => (
          <CommandGroup key={group.id} heading={headingOf(group)}>
            {group.items.map((item) => {
              const ItemIcon = item.icon;

              function goToPage() {
                closePalette();
                onNavigate(item.id);
              }

              return (
                <CommandItem
                  key={item.id}
                  value={`${group.id} ${item.label}`}
                  onSelect={goToPage}
                >
                  <ItemIcon />
                  {item.label}
                </CommandItem>
              );
            })}
          </CommandGroup>
        ))}
      </CommandList>
    </CommandDialog>
  );
}

'use client';

import {
  CircleCheckIcon,
  PlusIcon,
  UserRoundPlusIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Kbd } from '@/registry/ndeko/ui/kbd';

export type CreateKind = 'task' | 'invite';

type QuickCreateMenuProps = {
  onCreate: (kind: CreateKind) => void;
  side?: 'bottom' | 'right';
};

export function QuickCreateMenu({
  onCreate,
  side = 'bottom',
}: QuickCreateMenuProps) {
  function createTask() {
    onCreate('task');
  }

  function invitePeople() {
    onCreate('invite');
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
