import { motion, useReducedMotion } from 'motion/react';
import { useEffect, useRef, useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Kbd } from '@/registry/ndeko/ui/kbd';

import type { StatusId } from './data';
import { heightPresenceOf } from './motion-parts';
import { IssueTypeGem, StatusGlyph } from './task-glyphs';
import {
  DRAFT_TITLE_CELL,
  ID_CELL,
  PRIORITY_CELL,
  ROW_CLASS,
  TASK_GRID,
} from './task-grid';
import { statusOf } from './task-model';

type DraftRowProps = {
  status: StatusId;
  onCreate: (title: string) => void;
  onCancel: () => void;
};

export function DraftRow({ status, onCreate, onCancel }: DraftRowProps) {
  const shouldReduceMotion = useReducedMotion();
  const presence = heightPresenceOf(shouldReduceMotion);
  const inputRef = useRef<HTMLInputElement>(null);
  const [title, setTitle] = useState('');
  const statusName = statusOf(status).name;

  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  function submit() {
    const trimmed = title.trim();
    if (!trimmed) {
      onCancel();
      return;
    }
    onCreate(trimmed);
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Enter') {
      event.preventDefault();
      submit();
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      onCancel();
    }
  }

  function handleBlur() {
    const isEmpty = title.trim().length === 0;
    if (isEmpty) {
      onCancel();
    }
  }

  return (
    <motion.div
      role='row'
      {...presence}
      className={cn(TASK_GRID, ROW_CLASS, 'bg-primary/[0.04]')}
    >
      <div role='cell' className={PRIORITY_CELL} />
      <div role='cell' className={cn(ID_CELL, 'text-muted-foreground text-xs')}>
        New
      </div>
      <div role='cell' className='flex size-7 items-center justify-center'>
        <StatusGlyph status={status} />
      </div>
      <div
        role='cell'
        className={cn('flex min-w-0 items-center gap-2', DRAFT_TITLE_CELL)}
      >
        <IssueTypeGem type='task' />
        <input
          ref={inputRef}
          value={title}
          onChange={(event) => setTitle(event.target.value)}
          onKeyDown={handleKeyDown}
          onBlur={handleBlur}
          aria-label={`New task in ${statusName}`}
          placeholder='Task title'
          className='placeholder:text-muted-foreground/75 h-7 min-w-0 flex-1 bg-transparent text-base outline-none md:text-[13px]'
        />
        <Kbd className='hidden sm:inline-flex'>Enter</Kbd>
      </div>
    </motion.div>
  );
}

import {
  CircleCheckIcon,
  PlusIcon,
  SearchIcon,
  XIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import {
  activeFilterCountOf,
  countLabel,
  scopeOf,
  type Filters,
  type Scope,
} from './task-model';

type EmptyFrameProps = {
  icon: React.ReactNode;
  title: string;
  line: string;
  action: React.ReactNode;
};

function EmptyFrame({ icon, title, line, action }: EmptyFrameProps) {
  return (
    <div className='flex flex-col items-center px-6 py-16 text-center'>
      <span className='keycap-3d text-muted-foreground flex size-9 items-center justify-center rounded-lg'>
        {icon}
      </span>
      <p className='mt-4 text-sm font-medium'>{title}</p>
      <p className='text-muted-foreground mt-1 max-w-sm text-[13px] text-balance'>
        {line}
      </p>
      <div className='mt-4'>{action}</div>
    </div>
  );
}

function criteriaOf(query: string, filters: Filters) {
  const trimmed = query.trim();
  const filterCount = activeFilterCountOf(filters);
  const filterPhrase = countLabel(filterCount, 'filter', 'filters');
  const hasFilters = filterCount > 0;
  if (!trimmed) {
    return filterPhrase;
  }
  if (!hasFilters) {
    return `“${trimmed}”`;
  }
  return `“${trimmed}” with ${filterPhrase}`;
}

function reachOf(scope: Scope, scopeTotal: number) {
  const option = scopeOf(scope);
  if (scopeTotal === 0) {
    return `and there are no ${option.plural} yet`;
  }
  if (scopeTotal === 1) {
    return `clear them to see the one ${option.singular}`;
  }
  return `clear them to see all ${scopeTotal} ${option.plural}`;
}

function filteredLineOf(
  scope: Scope,
  query: string,
  filters: Filters,
  scopeTotal: number
) {
  const option = scopeOf(scope);
  const criteria = criteriaOf(query, filters);
  const reach = reachOf(scope, scopeTotal);
  return `No ${option.singular} matches ${criteria}, ${reach}`;
}

type FilteredEmptyProps = {
  scope: Scope;
  query: string;
  filters: Filters;
  scopeTotal: number;
  onClear: () => void;
};

export function FilteredEmpty({
  scope,
  query,
  filters,
  scopeTotal,
  onClear,
}: FilteredEmptyProps) {
  return (
    <EmptyFrame
      icon={<SearchIcon />}
      title='No tasks match'
      line={filteredLineOf(scope, query, filters, scopeTotal)}
      action={
        <Button variant='outline' onClick={onClear}>
          <XIcon />
          Clear filters
        </Button>
      }
    />
  );
}

type ScopeEmptyProps = {
  scope: Scope;
  onNewTask: () => void;
  onShowActive: () => void;
};

export function ScopeEmpty({
  scope,
  onNewTask,
  onShowActive,
}: ScopeEmptyProps) {
  if (scope === 'done') {
    return (
      <EmptyFrame
        icon={<CircleCheckIcon />}
        title='No finished tasks'
        line='Tasks moved to Done appear here'
        action={
          <Button variant='outline' onClick={onShowActive}>
            Show active tasks
          </Button>
        }
      />
    );
  }
  return (
    <EmptyFrame
      icon={<CircleCheckIcon />}
      title='No active tasks'
      line='All tasks are done, add one to plan what comes next'
      action={
        <Button onClick={onNewTask}>
          <PlusIcon />
          New task
        </Button>
      }
    />
  );
}

