type CommentComposerProps = {
  onSubmit: (body: string) => void;
  className?: string;
};

export function CommentComposer({ onSubmit, className }: CommentComposerProps) {
  const [body, setBody] = useState('');
  const me = currentUser();
  const trimmed = body.trim();
  const canSend = trimmed.length > 0;

  function submit() {
    if (!canSend) {
      return;
    }
    onSubmit(trimmed);
    setBody('');
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    submit();
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (event.key === 'Escape') {
      event.stopPropagation();
      event.currentTarget.blur();
      return;
    }
    const isCommand = event.metaKey || event.ctrlKey;
    if (event.key === 'Enter' && isCommand) {
      event.preventDefault();
      submit();
    }
  }

  return (
    <form
      onSubmit={handleSubmit}
      className={cn('flex items-start gap-2.5', className)}
    >
      <PersonAvatar person={me} className='mt-1 size-7 text-[10px]' />
      <div className='relative min-w-0 flex-1'>
        <Textarea
          value={body}
          onChange={(event) => setBody(event.target.value)}
          onKeyDown={handleKeyDown}
          rows={1}
          aria-label={`Comment as ${me.name}`}
          placeholder='Leave a comment'
          className='min-h-9 py-2 pe-24'
        />
        <Button
          type='submit'
          size='sm'
          disabled={!canSend}
          className='absolute end-1 bottom-1'
        >
          Comment
        </Button>
      </div>
    </form>
  );
}

'use client';

import { useEffect, useRef, useState } from 'react';
import { toast } from 'sonner';

const COPIED_FOR_MS = 1600;

export function useCopied() {
  const [isCopied, setIsCopied] = useState(false);
  const timers = useRef(new Set<ReturnType<typeof setTimeout>>());

  useEffect(() => {
    const pending = timers.current;
    return () => {
      pending.forEach((timer) => clearTimeout(timer));
    };
  }, []);

  async function copy(text: string) {
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      toast.error('Couldn’t copy', {
        description:
          'The browser blocked the clipboard, copy it from the address bar instead',
      });
      return;
    }
    setIsCopied(true);
    timers.current.forEach((timer) => clearTimeout(timer));
    timers.current.clear();
    const timer = setTimeout(() => setIsCopied(false), COPIED_FOR_MS);
    timers.current.add(timer);
  }

  return { isCopied, copy };
}

import { format } from 'date-fns';

import {
  CURRENT_USER_ID,
  TODAY,
  type FeedChange,
  type FeedComment,
  type StatusId,
  type Task,
} from './data';
import { statusOf } from './task-model';

function nowStamp() {
  const time = format(new Date(), 'HH:mm:ss');
  return `${TODAY}T${time}`;
}

function localIdOf(prefix: string) {
  return `${prefix}-${Date.now()}`;
}

function statusChangeOf(from: StatusId, to: StatusId): FeedChange {
  const fromName = statusOf(from).name;
  const toName = statusOf(to).name;
  return {
    kind: 'change',
    id: localIdOf('change'),
    authorId: CURRENT_USER_ID,
    at: nowStamp(),
    change: 'status',
    text: `moved it from ${fromName} to ${toName}`,
  };
}

export function patchedTask(task: Task, patch: Partial<Task>): Task {
  const next = { ...task, ...patch, updatedAt: nowStamp() };
  const nextStatus = patch.status;
  if (!nextStatus) {
    return next;
  }
  if (nextStatus === task.status) {
    return next;
  }
  const change = statusChangeOf(task.status, nextStatus);
  return { ...next, feed: [...task.feed, change] };
}

export function newTaskOf(
  number: number,
  status: StatusId,
  title: string,
  assigneeIds: string[]
): Task {
  const stamp = nowStamp();
  const created: FeedChange = {
    kind: 'change',
    id: localIdOf('created'),
    authorId: CURRENT_USER_ID,
    at: stamp,
    change: 'created',
    text: 'created the task',
  };
  return {
    id: `mos-${number}`,
    number,
    title,
    type: 'task',
    status,
    priority: 'none',
    labelIds: [],
    assigneeIds,
    createdAt: stamp,
    updatedAt: stamp,
    reporterId: CURRENT_USER_ID,
    description: [],
    children: [],
    feed: [created],
    worked: [],
  };
}

export function commentOf(body: string): FeedComment {
  return {
    kind: 'comment',
    id: localIdOf('comment'),
    authorId: CURRENT_USER_ID,
    at: nowStamp(),
    body,
  };
}

export function withComment(task: Task, comment: FeedComment) {
  return { ...task, feed: [...task.feed, comment], updatedAt: comment.at };
}

import {
  addDays,
  format,
  isSameDay,
  nextMonday,
  parseISO,
  subDays,
} from 'date-fns';

import { TODAY, type FeedItem } from './data';
import { keyOf } from './task-model';

export type FeedFilter = 'all' | 'comments' | 'history';

export type DayGroup = {
  day: string;
  label: string;
  items: FeedItem[];
};

export type DatePreset = {
  label: string;
  date: string;
};

export function isFeedFilter(value: unknown): value is FeedFilter {
  const isAll = value === 'all';
  const isComments = value === 'comments';
  const isHistory = value === 'history';
  return isAll || isComments || isHistory;
}

export function taskUrlOf(number: number) {
  return `https://example.com/mossline/tasks/${keyOf(number)}`;
}

export function durationLabel(minutes: number) {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  const paddedRest = String(rest).padStart(2, '0');
  return `${hours}h ${paddedRest}m`;
}

export function shortDateOf(iso: string) {
  return format(parseISO(iso), 'MMM d');
}

export function longDateOf(iso: string) {
  return format(parseISO(iso), 'EEE, MMM d');
}

export function timeOf(iso: string) {
  return format(parseISO(iso), 'HH:mm');
}

function isoDayOf(date: Date) {
  return format(date, 'yyyy-MM-dd');
}

export function datePresetsOf(): DatePreset[] {
  const today = parseISO(TODAY);
  return [
    { label: 'Today', date: TODAY },
    { label: 'Tomorrow', date: isoDayOf(addDays(today, 1)) },
    { label: 'Next Monday', date: isoDayOf(nextMonday(today)) },
    { label: 'In a week', date: isoDayOf(addDays(today, 7)) },
    { label: 'In two weeks', date: isoDayOf(addDays(today, 14)) },
  ];
}

export const ESTIMATE_PRESETS = [30, 60, 120, 240, 480];

function dayLabelOf(day: string) {
  const date = parseISO(day);
  const today = parseISO(TODAY);
  if (isSameDay(date, today)) {
    return 'Today';
  }
  if (isSameDay(date, subDays(today, 1))) {
    return 'Yesterday';
  }
  return format(date, 'EEE, MMM d');
}

function matchesFeedFilter(item: FeedItem, filter: FeedFilter) {
  if (filter === 'comments') {
    return item.kind === 'comment';
  }
  if (filter === 'history') {
    return item.kind === 'change';
  }
  return true;
}

export function feedCountsOf(items: FeedItem[]): Record<FeedFilter, number> {
  const comments = items.filter((item) => item.kind === 'comment').length;
  const history = items.length - comments;
  return { all: items.length, comments, history };
}

export function dayGroupsOf(items: FeedItem[], filter: FeedFilter) {
  const shown = items.filter((item) => matchesFeedFilter(item, filter));
  const sorted = [...shown].sort((first, second) =>
    first.at.localeCompare(second.at)
  );
  const groups: DayGroup[] = [];
  for (const item of sorted) {
    const day = item.at.slice(0, 10);
    const last = groups.at(-1);
    const isSameGroup = last?.day === day;
    if (isSameGroup) {
      last.items.push(item);
      continue;
    }
    groups.push({ day, label: dayLabelOf(day), items: [item] });
  }
  return groups;
}

