            <span className='text-muted-foreground text-xs tabular-nums'>
              {unreadLabelOf(unreadCount)}
            </span>
          </div>
          <Button
            variant='ghost'
            size='sm'
            disabled={!hasUnread}
            onClick={onMarkAllRead}
            className='text-muted-foreground'
