'use client';

import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  MeasuringStrategy,
  MouseSensor,
  TouchSensor,
  defaultDropAnimationSideEffects,
  useSensor,
  useSensors,
  type Announcements,
  type CollisionDetection,
  type DragEndEvent,
  type DragMoveEvent,
  type DragOverEvent,
  type DragStartEvent,
  type DropAnimation,
  type UniqueIdentifier,
} from '@dnd-kit/core';
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import { useMotionValue, useReducedMotion } from 'motion/react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { PlusIcon } from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { BoardLane } from './board-lane';
import {
  detectBoardCollision,
  laneOf,
  moveAcrossLanes,
  reorderInLane,
  targetLaneOf,
} from './board-moves';
import {
  LANES,
  cardsOf,
  columnsOf,
  type BoardCard,
  type Columns,
  type LaneId,
} from './board-model';
import { TEAM_NAME, type Task } from './data';
import { OverlayCard } from './drag-overlay-card';

const MEASURING = { droppable: { strategy: MeasuringStrategy.Always } };

const DROP_ANIMATION: DropAnimation = {
  duration: 220,
  easing: 'cubic-bezier(0.23, 1, 0.32, 1)',
  sideEffects: defaultDropAnimationSideEffects({
    styles: { active: { opacity: '0.4' } },
  }),
};

const SCREEN_READER_INSTRUCTIONS = {
  draggable:
    'To pick up a task, press Space or Enter. Use the arrow keys to move it between lanes and cards, Space or Enter to drop it, Escape to cancel.',
};

const DEFAULT_COMPOSER_LANE: LaneId = 'todo';

function dropAnimationOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return null;
  }
  return DROP_ANIMATION;
}

function laneLabelOf(laneId: LaneId | null) {
  const lane = LANES.find((candidate) => candidate.id === laneId);
  if (lane) {
    return lane.label;
  }
  return 'the board';
}

function countLabel(count: number, singular: string, plural: string) {
  if (count === 1) {
    return `1 ${singular}`;
  }
  return `${count} ${plural}`;
}

type BoardPageProps = {
  tasks: Task[];
  onColumnsChange: (columns: Columns) => void;
  onCreateTask: (laneId: LaneId, title: string) => string;
};

export function BoardPage({
  tasks: sharedTasks,
  onColumnsChange,
  onCreateTask,
}: BoardPageProps) {
  const [columns, setColumns] = useState<Columns>(() => columnsOf(sharedTasks));
  const tasks = useMemo(() => cardsOf(sharedTasks), [sharedTasks]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [targetLaneId, setTargetLaneId] = useState<LaneId | null>(null);
  const [composerLaneId, setComposerLaneId] = useState<LaneId | null>(null);
  const [newTaskIds, setNewTaskIds] = useState<ReadonlySet<string>>(
    () => new Set()
  );
  const columnsRef = useRef(columns);
  const snapshotRef = useRef<Columns | null>(null);
  const lastOverIdRef = useRef<UniqueIdentifier | null>(null);
  const movedLaneRef = useRef(false);
  const dragX = useMotionValue(0);
  const shouldReduceMotion = useReducedMotion();
  const sensors = useSensors(
    useSensor(MouseSensor, { activationConstraint: { distance: 4 } }),
    useSensor(TouchSensor, {
      activationConstraint: { delay: 180, tolerance: 6 },
    }),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const allTaskIds = Object.values(columns).flat();
  const trackedCount = allTaskIds.filter(
    (taskId) => tasks[taskId].isTracked
  ).length;
  const taskCountText = countLabel(allTaskIds.length, 'task', 'tasks');
  const timerText = countLabel(trackedCount, 'timer running', 'timers running');
  const metaText = `${taskCountText} · ${timerText}`;
  let activeTask: BoardCard | null = null;
  if (activeId) {
    activeTask = tasks[activeId];
  }

  useEffect(() => {
    columnsRef.current = columns;
    const frame = requestAnimationFrame(() => {
      movedLaneRef.current = false;
    });
    return () => cancelAnimationFrame(frame);
  }, [columns]);

  const collisionDetection = useCallback<CollisionDetection>((args) => {
    const hits = detectBoardCollision(args, columnsRef.current);
    if (hits.length > 0) {
      lastOverIdRef.current = hits[0].id;
      return hits;
    }
    if (movedLaneRef.current) {
      lastOverIdRef.current = args.active.id;
    }
    const lastOverId = lastOverIdRef.current;
    if (lastOverId) {
      return [{ id: lastOverId }];
    }
    return [];
  }, []);

  const announcements: Announcements = {
    onDragStart({ active }) {
      const lane = laneOf(columnsRef.current, String(active.id));
      return `Picked up ${tasks[String(active.id)].number} in ${laneLabelOf(lane)}`;
    },
    onDragOver({ active, over }) {
      if (!over) {
        return `${tasks[String(active.id)].number} is no longer over a lane`;
      }
      const lane = targetLaneOf(columnsRef.current, String(over.id));
      return `${tasks[String(active.id)].number} is over ${laneLabelOf(lane)}`;
    },
    onDragEnd({ active }) {
      const lane = laneOf(columnsRef.current, String(active.id));
      return `${tasks[String(active.id)].number} dropped in ${laneLabelOf(lane)}`;
    },
    onDragCancel({ active }) {
      return `Moving ${tasks[String(active.id)].number} was cancelled`;
    },
  };

  function handleDragStart({ active }: DragStartEvent) {
    const taskId = String(active.id);
    snapshotRef.current = columns;
    dragX.set(0);
    setActiveId(taskId);
    setTargetLaneId(laneOf(columns, taskId));
    setComposerLaneId(null);
  }

  function handleDragMove({ delta }: DragMoveEvent) {
    dragX.set(delta.x);
  }

  function handleDragOver({ active, over }: DragOverEvent) {
    if (!over) {
      return;
    }
    const overLane = targetLaneOf(columnsRef.current, String(over.id));
    setTargetLaneId(overLane);
    const fromLane = laneOf(columnsRef.current, String(active.id));
    const isOtherLane = fromLane !== overLane;
    if (!isOtherLane) {
      return;
    }
    movedLaneRef.current = true;
    setColumns((previous) => moveAcrossLanes(previous, active, over));
  }

  function handleDragEnd({ active, over }: DragEndEvent) {
    setActiveId(null);
    setTargetLaneId(null);
    snapshotRef.current = null;
    const currentColumns = columnsRef.current;
    if (!over) {
      onColumnsChange(currentColumns);
      return;
    }
    const activeTaskId = String(active.id);
    const overId = String(over.id);
    const nextColumns = reorderInLane(currentColumns, activeTaskId, overId);
    setColumns(nextColumns);
    onColumnsChange(nextColumns);
  }

  function handleDragCancel() {
    const snapshot = snapshotRef.current;
    if (snapshot) {
      setColumns(snapshot);
    }
    snapshotRef.current = null;
    setActiveId(null);
    setTargetLaneId(null);
  }

  const openComposer = useCallback((laneId: LaneId) => {
    setComposerLaneId(laneId);
  }, []);

  const closeComposer = useCallback(() => {
    setComposerLaneId(null);
  }, []);

  const createTask = useCallback(
    (laneId: LaneId, title: string) => {
      const taskId = onCreateTask(laneId, title);
      setColumns((previous) => ({
        ...previous,
        [laneId]: [...previous[laneId], taskId],
      }));
      setNewTaskIds((previous) => new Set(previous).add(taskId));
    },
    [onCreateTask]
  );

  function openDefaultComposer() {
    setComposerLaneId(DEFAULT_COMPOSER_LANE);
  }

  return (
    <div className='flex min-h-0 w-full flex-1 flex-col'>
      <div className='hairline-b border-border flex shrink-0 flex-wrap items-center gap-x-3 gap-y-2 px-4 py-3 md:px-6'>
        <div className='flex min-w-0 items-baseline gap-2'>
          <h1 className='truncate text-lg font-semibold'>{`${TEAM_NAME} board`}</h1>
          <span className='text-muted-foreground text-xs tabular-nums'>
            {metaText}
          </span>
        </div>
        <Button onClick={openDefaultComposer} className='ml-auto'>
          <PlusIcon />
          Create task
        </Button>
      </div>
      <DndContext
        sensors={sensors}
        collisionDetection={collisionDetection}
        measuring={MEASURING}
        accessibility={{
          announcements,
          screenReaderInstructions: SCREEN_READER_INSTRUCTIONS,
        }}
        onDragStart={handleDragStart}
        onDragMove={handleDragMove}
        onDragOver={handleDragOver}
        onDragEnd={handleDragEnd}
        onDragCancel={handleDragCancel}
      >
        <div className='min-h-0 flex-1 overflow-x-auto overscroll-x-contain max-md:snap-x max-md:snap-proximity max-md:scroll-px-4'>
          <div className='flex h-full w-max items-start gap-3 px-4 py-3 md:px-6'>
            {LANES.map((lane) => (
              <BoardLane
                key={lane.id}
                lane={lane}
                taskIds={columns[lane.id]}
                tasks={tasks}
                newTaskIds={newTaskIds}
                isTarget={targetLaneId === lane.id}
                isComposerOpen={composerLaneId === lane.id}
                emptyLine='Drop a task here or create one'
                onOpenComposer={openComposer}
                onCloseComposer={closeComposer}
                onCreateTask={createTask}
              />
            ))}
          </div>
        </div>
        <DragOverlay dropAnimation={dropAnimationOf(shouldReduceMotion)}>
          {activeTask && <OverlayCard task={activeTask} dragX={dragX} />}
        </DragOverlay>
      </DndContext>
    </div>
  );
}

'use client';

import { useDroppable } from '@dnd-kit/core';
import {
  SortableContext,
  useSortable,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
  useReducedMotion,
} from 'motion/react';
import { memo, useEffect, useRef, useState } from 'react';

import { PlusIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Input } from '@/registry/ndeko/ui/input';

import {
  CARD_SURFACE,
  TRACKED_CARD,
  TaskCardBody,
  formatDuration,
} from './card-parts';
import type { BoardCard, LaneId, LaneMeta } from './board-model';

const SORT_TRANSITION = {
  duration: 220,
  easing: 'cubic-bezier(0.23, 1, 0.32, 1)',
};

const ENTER_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const CARD_PRESENCE: Variants = {
  hidden: { height: 0, opacity: 0, overflow: 'hidden' },
  shown: {
    height: 'auto',
    opacity: 1,
    transition: ENTER_IN,
    transitionEnd: { overflow: 'visible' },
  },
};

const CARD_FADE: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1, transition: ENTER_IN },
};

const DIGIT_SHIFT_PX = 8;

const DIGIT_TRANSITION: Transition = { duration: 0.18, ease: [0.2, 0, 0, 1] };

const DIGIT_VARIANTS: Variants = {
  enter: (direction: number) => {
    const offset = direction * DIGIT_SHIFT_PX;
    return { opacity: 0, y: offset };
  },
  visible: { opacity: 1, y: 0 },
  exit: (direction: number) => {
    const offset = direction * DIGIT_SHIFT_PX;
    return { opacity: 0, y: -offset };
  },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0 },
};

type CountState = { value: number; direction: number };

function sortTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return null;
  }
  return SORT_TRANSITION;
}

function cardVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return CARD_FADE;
  }
  return CARD_PRESENCE;
}

function initialOf(isNew: boolean) {
  if (isNew) {
    return 'hidden';
  }
  return false;
}

function digitVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return DIGIT_VARIANTS;
}

function directionOf(previous: number, next: number) {
  if (next > previous) {
    return 1;
  }
  return -1;
}

function taskCountLabel(count: number) {
  if (count === 1) {
    return '1 task';
  }
  return `${count} tasks`;
}

function cardLabelOf(task: BoardCard) {
  const worked = formatDuration(task.workedMinutes);
  return `${task.number} ${task.title}, ${worked} worked`;
}

function LaneCount({ value }: { value: number }) {
  const shouldReduceMotion = useReducedMotion();
  const [shown, setShown] = useState<CountState>({ value, direction: 1 });
  const variants = digitVariantsOf(shouldReduceMotion);

  if (shown.value !== value) {
    const direction = directionOf(shown.value, value);
    setShown({ value, direction });
  }

  return (
    <span className='bg-foreground/[0.06] text-muted-foreground relative inline-flex h-5 min-w-5 items-center justify-center overflow-hidden rounded-sm px-1.5 text-xs tabular-nums'>
      <AnimatePresence
        mode='popLayout'
        initial={false}
        custom={shown.direction}
      >
        <motion.span
          key={value}
          custom={shown.direction}
          variants={variants}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={DIGIT_TRANSITION}
        >
          {value}
        </motion.span>
      </AnimatePresence>
      <span className='sr-only'>{` ${taskCountLabel(value)}`}</span>
    </span>
  );
}

export function LaneTile({ lane }: { lane: LaneMeta }) {
  const LaneGlyph = lane.icon;
  const tileStyle = { '--chip': lane.color } as React.CSSProperties;

  return (
    <span
      style={tileStyle}
      className='chip-3d flex size-5 shrink-0 items-center justify-center rounded-md'
    >
      <LaneGlyph className='size-3' strokeWidth={2.25} />
    </span>
  );
}

function SortableTaskCard({
  task,
  isNew,
}: {
  task: BoardCard;
  isNew: boolean;
}) {
  const shouldReduceMotion = useReducedMotion();
  const cardVariants = cardVariantsOf(shouldReduceMotion);
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({
    id: task.id,
    transition: sortTransitionOf(shouldReduceMotion),
  });
  const style = {
    transform: CSS.Translate.toString(transform),
    transition,
  } as React.CSSProperties;

  return (
    <motion.li
      variants={cardVariants}
      initial={initialOf(isNew)}
      animate='shown'
    >
      <div
        ref={setNodeRef}
        style={style}
        {...attributes}
        {...listeners}
        aria-label={cardLabelOf(task)}
        className={cn(
          CARD_SURFACE,
          task.isTracked && TRACKED_CARD,
          'focus-visible:ring-ring/25 cursor-grab touch-manipulation outline-none focus-visible:ring-[3px] active:cursor-grabbing',
          '[contain-intrinsic-size:auto_9rem] [content-visibility:auto]',
          isDragging && 'opacity-40'
        )}
      >
        <TaskCardBody task={task} />
      </div>
    </motion.li>
  );
}

function LaneComposer({
  laneLabel,
  onCreate,
  onClose,
}: {
  laneLabel: string;
  onCreate: (title: string) => void;
  onClose: () => void;
}) {
  const [title, setTitle] = useState('');
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    formRef.current?.scrollIntoView({ block: 'nearest' });
  }, []);

  function changeTitle(event: React.ChangeEvent<HTMLInputElement>) {
    setTitle(event.target.value);
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === 'Escape') {
      event.preventDefault();
      onClose();
    }
  }

  function create(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const trimmed = title.trim();
    if (trimmed.length === 0) {
      return;
    }
    onCreate(trimmed);
    setTitle('');
  }

  return (
    <form
      ref={formRef}
      onSubmit={create}
      className={cn(CARD_SURFACE, 'flex flex-col gap-2 p-2')}
    >
      <Input
        autoFocus
        value={title}
        placeholder='Task title'
        aria-label={`Title of the new task in ${laneLabel}`}
        onChange={changeTitle}
        onKeyDown={handleKeyDown}
      />
      <div className='flex items-center justify-end gap-1'>
        <Button type='button' variant='ghost' size='sm' onClick={onClose}>
          Cancel
        </Button>
        <Button type='submit' size='sm'>
          Add task
        </Button>
      </div>
    </form>
  );
}

