'use client';

import {
  motion,
  type MotionValue,
  type Transition,
  useReducedMotion,
  useSpring,
  useTransform,
  useVelocity,
} from 'motion/react';

import { TaskCardBody } from './card-parts';
import type { BoardCard } from './board-model';

const VELOCITY_RANGE = [-1400, 0, 1400];

const TILT_RANGE = [-5, 0, 5];

const TILT_SPRING = { stiffness: 380, damping: 26, mass: 0.6 };

const LIFT: Transition = { type: 'spring', bounce: 0, duration: 0.25 };

const INSTANT: Transition = { duration: 0 };

function liftOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return LIFT;
}

function liftScaleOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 1;
  }
  return 1.02;
}

type OverlayCardProps = {
  task: BoardCard;
  dragX: MotionValue<number>;
};

/** The card under the pointer: it leans with the speed of the drag and settles on a spring when the pointer slows. */
export function OverlayCard({ task, dragX }: OverlayCardProps) {
  const shouldReduceMotion = useReducedMotion();
  const velocity = useVelocity(dragX);
  const tiltTarget = useTransform(velocity, VELOCITY_RANGE, TILT_RANGE, {
    clamp: true,
  });
  const tilt = useSpring(tiltTarget, TILT_SPRING);
  const noTilt = useTransform(tilt, () => 0);
  let rotate = tilt;
  if (shouldReduceMotion) {
    rotate = noTilt;
  }

  return (
    <motion.div
      style={{ rotate }}
      initial={{ scale: 1 }}
      animate={{ scale: liftScaleOf(shouldReduceMotion) }}
      transition={liftOf(shouldReduceMotion)}
      className='surface-raised cursor-grabbing rounded-lg'
    >
      <TaskCardBody task={task} />
    </motion.div>
  );
}

import {
  closestCenter,
  closestCorners,
  pointerWithin,
  type Active,
  type CollisionDetection,
  type Over,
} from '@dnd-kit/core';
import { arrayMove } from '@dnd-kit/sortable';

import type { Columns, LaneId } from './board-model';

export function isLaneId(columns: Columns, id: string): id is LaneId {
  return Object.prototype.hasOwnProperty.call(columns, id);
}

export function laneOf(columns: Columns, taskId: string): LaneId | null {
  const lanes = Object.keys(columns) as LaneId[];
  const lane = lanes.find((laneId) => columns[laneId].includes(taskId));
  if (lane) {
    return lane;
  }
  return null;
}

export function targetLaneOf(columns: Columns, overId: string) {
  if (isLaneId(columns, overId)) {
    return overId;
  }
  return laneOf(columns, overId);
}

/** Inside the lane under the pointer, the closest card wins; an empty lane is the target itself. */
export function detectBoardCollision(
  args: Parameters<CollisionDetection>[0],
  columns: Columns
) {
  const hasPointer = Boolean(args.pointerCoordinates);
  if (!hasPointer) {
    return closestCorners(args);
  }
  const pointerHits = pointerWithin(args);
  const laneHit = pointerHits.find((hit) => isLaneId(columns, String(hit.id)));
  if (!laneHit) {
    return pointerHits;
  }
  const laneTaskIds = columns[laneHit.id as LaneId];
  const cardContainers = args.droppableContainers.filter((container) =>
    laneTaskIds.includes(String(container.id))
  );
  const isEmptyLane = cardContainers.length === 0;
  if (isEmptyLane) {
    return [laneHit];
  }
  return closestCenter({ ...args, droppableContainers: cardContainers });
}

function isBelowOver(active: Active, over: Over) {
  const translated = active.rect.current.translated;
  if (!translated) {
    return false;
  }
  const overMiddle = over.rect.top + over.rect.height / 2;
  return translated.top > overMiddle;
}

/** Moves the dragged card into the lane under it, before or after the card it hovers. */
export function moveAcrossLanes(
  columns: Columns,
  active: Active,
  over: Over
): Columns {
  const activeId = String(active.id);
  const overId = String(over.id);
  const fromLane = laneOf(columns, activeId);
  const toLane = targetLaneOf(columns, overId);
  if (!fromLane) {
    return columns;
  }
  if (!toLane) {
    return columns;
  }
  if (fromLane === toLane) {
    return columns;
  }
  const fromItems = columns[fromLane].filter((id) => id !== activeId);
  const toItems = columns[toLane];
  let insertAt = toItems.length;
  const isOverCard = !isLaneId(columns, overId);
  if (isOverCard) {
    const overIndex = toItems.indexOf(overId);
    insertAt = overIndex;
    if (isBelowOver(active, over)) {
      insertAt = overIndex + 1;
    }
  }
  const nextToItems = [
    ...toItems.slice(0, insertAt),
    activeId,
    ...toItems.slice(insertAt),
  ];
  return { ...columns, [fromLane]: fromItems, [toLane]: nextToItems };
}

/** Reorders the dragged card inside its lane once it is dropped. */
export function reorderInLane(
  columns: Columns,
  activeId: string,
  overId: string
): Columns {
  const lane = laneOf(columns, activeId);
  if (!lane) {
    return columns;
  }
  const items = columns[lane];
  const oldIndex = items.indexOf(activeId);
  const newIndex = items.indexOf(overId);
  const isMissing = newIndex === -1;
  const isSamePlace = oldIndex === newIndex;
  if (isMissing || isSamePlace) {
    return columns;
  }
  return { ...columns, [lane]: arrayMove(items, oldIndex, newIndex) };
}

import {
  BOARD_ORDER,
  STATUS_ICONS,
  type IssueTypeId,
  type PriorityId,
  type Size,
  type StatusId,
  type Task,
} from './data';
import { patchedTask } from './task-edits';
import { statusOf, taskKeyOf } from './task-model';

export type LaneId = StatusId;

export type Columns = Record<LaneId, string[]>;

export type LaneMeta = ReturnType<typeof laneMetaOf>;

export type BoardCard = {
  id: string;
  number: string;
  title: string;
  type: IssueTypeId;
  priority: PriorityId;
  size: Size | null;
  labelIds: string[];
  assigneeIds: string[];
  estimateMinutes: number;
  workedMinutes: number;
  isTracked: boolean;
};

function laneMetaOf(id: LaneId) {
  const status = statusOf(id);
  return {
    id,
    label: status.name,
    color: status.color,
    icon: STATUS_ICONS[id],
  };
}

export const LANES = BOARD_ORDER.map(laneMetaOf);

function workedMinutesOf(task: Task) {
  let total = 0;
  for (const entry of task.worked) {
    total += entry.minutes;
  }
  return total;
}

function cardOf(task: Task): BoardCard {
  return {
    id: task.id,
    number: taskKeyOf(task),
    title: task.title,
    type: task.type,
    priority: task.priority,
    size: task.size ?? null,
    labelIds: task.labelIds,
    assigneeIds: task.assigneeIds,
    estimateMinutes: task.estimateMinutes ?? 0,
    workedMinutes: workedMinutesOf(task),
    isTracked: Boolean(task.trackedById),
  };
}

export function cardsOf(tasks: Task[]) {
  const cards: Record<string, BoardCard> = {};
  for (const task of tasks) {
    cards[task.id] = cardOf(task);
  }
  return cards;
}

export function columnsOf(tasks: Task[]): Columns {
  const columns: Columns = {
    backlog: [],
    todo: [],
    in_progress: [],
    in_review: [],
    done: [],
  };
  for (const task of tasks) {
    columns[task.status].push(task.id);
  }
  return columns;
}

function movedTask(task: Task, status: StatusId) {
  if (task.status === status) {
    return task;
  }
  return patchedTask(task, { status });
}

/** The board order becomes the order of the tasks, and each lane the status of its cards. */
export function tasksInColumnsOf(tasks: Task[], columns: Columns) {
  const remaining = new Map(tasks.map((task) => [task.id, task]));
  const placed: Task[] = [];
  for (const laneId of BOARD_ORDER) {
    for (const taskId of columns[laneId]) {
      const task = remaining.get(taskId);
      if (!task) {
        continue;
      }
      placed.push(movedTask(task, laneId));
      remaining.delete(taskId);
    }
  }
  const unplaced = [...remaining.values()];
  return [...placed, ...unplaced];
}

